import{c as t,Q as e,j as n,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2308.08155","title":"AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2308.08155,"authors":["Qingyun Wu","Gagan Bansal","Jieyu Zhang","Yiran Wu","Beibin Li","Erkang Zhu","Li Jiang","Xiaoyun Zhang","Shaokun Zhang","Jiale Liu","Ahmed Hassan Awadallah","Ryen W. White","Doug Burger","Chi Wang"],"domains":["cs.AI","cs.CL"],"pdf_path":"pdfs/2308.08155.pdf","published_date":"2023-08-16T00:00:00.000Z","tags":["multi-agent","conversation-framework","conversable-agent","microsoft","llm"]},"headers":[],"relativePath":"research/papers/2023-08-16-autogen-multi-agent-conversation-framework-2308-08155.md","filePath":"research/papers/2023-08-16-autogen-multi-agent-conversation-framework-2308-08155.md","lastUpdated":1785909234000}'),i={name:"research/papers/2023-08-16-autogen-multi-agent-conversation-framework-2308-08155.md"};function r(s,a,l,g,u,c){return e(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="autogen-enabling-next-gen-llm-applications-via-multi-agent-conversation" tabindex="-1">AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation <a class="header-anchor" href="#autogen-enabling-next-gen-llm-applications-via-multi-agent-conversation" aria-label="Permalink to &quot;AutoGen: Enabling Next-Gen LLM Applications via Multi-Agent Conversation&quot;">​</a></h1><p><strong>arXiv</strong>: 2308.08155 | <strong>發表</strong>: 2023-08-16 | <strong>PDF</strong>: 2023-08-16-autogen-multi-agent-conversation-framework-2308-08155.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>Microsoft Research 提出通用 multi-agent 對話框架，允許開發者以自然語言 + 程式碼定義 agent 互動行為。核心抽象：<strong>conversable agent</strong>（可被任何組合的 LLM / 工具 / 人類輸入驅動）+ <strong>conversation pattern</strong>（靈活配置通訊拓撲）。目標：把「multi-agent 協作」降為可程式化的基礎設施，而非任務特定實現。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>ConversableAgent</strong>：統一介面，每個 agent 可配置 LLM backend、tool calling、human-in-loop，三者任意組合</li><li><strong>GroupChat</strong>：N agent 輪流發言的廣播模式，搭配 GroupChatManager 控制發言順序</li><li><strong>兩人對話（Two-Agent Chat）</strong>：最小單元，UserProxy + AssistantAgent；UserProxy 可轉發人類輸入或自動執行工具</li><li><strong>Nested Chat</strong>：一個 agent 可以在內部啟動另一個子對話（遞迴委派）</li><li>支援 termination condition、code execution sandbox、custom reply function</li></ul><h2 id="關鍵發現與數據" tabindex="-1">關鍵發現與數據 <a class="header-anchor" href="#關鍵發現與數據" aria-label="Permalink to &quot;關鍵發現與數據&quot;">​</a></h2><ul><li>展示 6 個應用場景：math（GSM8K）、coding、Q&amp;A、operations research、online decision-making、entertainment</li><li>在 math 任務中，AutoGen multi-agent 方案優於 GPT-4 單 agent baseline（具體見全文表格）</li><li>透過 human-in-loop 混合模式（automatic + manual）在敏感 coding 任務中保持安全性</li><li>框架在 43 頁論文附錄中展示 30+ 頁實際案例，強調通用性</li></ul><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>Conversable agent 是最小可組合單元</strong>：不要為每個任務重新設計 agent；用同一介面 + 不同配置組合</li><li><strong>GroupChat 適合廣播式決策，Two-Agent 適合有序 pipeline</strong>：通訊拓撲決定協作語義，設計時先選拓撲</li><li><strong>Nested Chat 實現遞迴委派</strong>：orchestrator 可以是 agent，worker 也可以在內部是 orchestrator，天然支援 hierarchical</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;AutoGen enables diverse LLM-based applications using multi-agent conversations. It provides a multi-agent conversation framework as a high-level abstraction. With this framework, one can build LLM applications by composing multiple agents that can converse with each other to accomplish tasks... Agents in AutoGen can operate in various modes that employ combinations of LLMs, human inputs, and tools.&quot;</p></blockquote>',12)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
